-- MES-8a · LOCAL harness only (never live): the seven real roles' codes as read from live role_permissions after the migration (read-only, 2026-10-16 22:50 SGT).
-- Run as postgres on the rebuild before local-seed-data.sql:  psql "<local dsn>" -v ON_ERROR_STOP=1 -f local-seed-clones.sql
DO $r$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticator') THEN CREATE ROLE authenticator LOGIN NOINHERIT; END IF; END $r$;
GRANT anon, authenticated, service_role TO authenticator;
DO $c$ DECLARE r uuid; BEGIN
END $c$;
